// ELEMENTS:
// 1. Foto do imóvel a ocupar o quadro inteiro (src) — entra primeiro
// 2. Pill coral "NOVO IMÓVEL" no topo à esquerda (tag)
// 3. Etiqueta de preço branca, cantos retos, na costura à direita (price)
// 4. Painel azul com o corte diagonal no topo, a subir para a direita
// 5. Eyebrow de localização "LISBOA · ALVALADE" (location)
// 6. Título "T3 COM VARANDA" 800 itálico maiúsculas (title / anim.text)
// 7. Linha de factos "120 m² · 3 quartos · 2 WC · garagem" (facts)
// 8. Pill CTA coral "Ligue já +351 963 050 290" (cta)
// 9. Avatar circular com anel branco (avatar)
// 10. Nome do agente "Manuel Reis" (name)
// 11. Logótipo da rede à direita (logo, ou logoText + logoSub)
// 12. Linha legal "IAD PORTUGAL S.A. | AMI: 11220" (legal)
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const PRIMARY = "#05B8E6";
const ACCENT = "#F06052";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const PHOTO_BG = "#EEF0EF";
const AVATAR_BG = "#B4B7B8";

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ImovelStoryReveal: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const params: Record<string, unknown> = anim.params ?? {};
  const s = (key: string): string => {
    const v = params[key];
    return typeof v === "string" ? v.trim() : typeof v === "number" ? String(v) : "";
  };

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = s("tag");
  const price = s("price");
  const location = s("location");
  const title = s("title") || String(anim.text ?? "").trim();
  const facts = s("facts");
  const cta = s("cta");
  const name = s("name");
  const legal = s("legal");
  const logoText = s("logoText");
  const logoSub = s("logoSub");

  // Layout: k converts mockup px (363 wide portrait) into frame px.
  const portrait = format === "portrait";
  const land = format === "landscape";
  const k = portrait ? W / 363 : land ? H / 490 : H / 480;
  const mx = 24 * k;
  const seamL = (portrait ? 0.617 : land ? 0.6 : 0.53) * H;
  const seamR = (portrait ? 0.572 : land ? 0.49 : 0.44) * H;
  const tagTop = portrait ? 0.13 * H : 0.08 * H;
  const bottomPad = portrait ? 60 * k : 24 * k;

  const colW = W - 2 * mx;
  const headBase = 28 * k;
  const fitChars = (colW / (headBase * 0.7)) * (land ? 1 : 2);
  const headSize = title.length > fitChars ? Math.max(0.55, fitChars / title.length) * headBase : headBase;

  // Timing: everything settles by 60% of the layer.
  const T = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (f: number) => Math.round(f * T);
  const pop = (start: number, len: number, damping = 12) =>
    spring({
      frame: frame - at(start),
      fps,
      durationInFrames: Math.max(2, at(len)),
      config: { damping, mass: 0.7, stiffness: 140 },
    });
  const move = (p: number, dy: number, scale = false): React.CSSProperties => ({
    opacity: interpolate(p, [0, 0.35], [0, 1], clamp),
    transform: `translateY(${(1 - p) * dy}px)${scale ? ` scale(${0.6 + 0.4 * p})` : ""}`,
  });

  const heroIris = interpolate(frame, [0, at(0.2)], [50, 0], clamp);
  const heroScale = interpolate(frame, [0, at(0.36)], [1.18, 1], clamp);
  const pPanel = pop(0.16, 0.18, 18);
  const pTag = pop(0.24, 0.14, 10);
  const pPrice = pop(0.3, 0.14, 10);
  const pEyebrow = pop(0.32, 0.12, 18);
  const pHead = pop(0.35, 0.13, 14);
  const pFacts = pop(0.39, 0.12, 18);
  const pCta = pop(0.43, 0.13, 9);
  const pFooter = pop(0.47, 0.12, 12);
  const pLegal = pop(0.5, 0.1, 18);

  const ctaEl = cta ? (
    <div
      style={{
        alignSelf: land ? "center" : "flex-start",
        background: ACCENT,
        color: WHITE,
        borderRadius: 999,
        padding: `${6 * k}px ${14 * k}px`,
        fontFamily: FONTS.body,
        fontWeight: 800,
        fontStyle: "italic",
        fontSize: 16 * k,
        lineHeight: 1.1,
        transformOrigin: "left center",
        ...move(pCta, 30 * k, true),
      }}
    >
      {cta}
    </div>
  ) : null;

  const logoEl = logo ? (
    <Img src={logo} style={{ height: 26 * k, width: "auto", objectFit: "contain" }} />
  ) : logoText ? (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", color: WHITE, fontFamily: FONTS.body, lineHeight: 0.9 }}>
      <span style={{ fontWeight: 800, fontSize: 20 * k, letterSpacing: "-0.02em" }}>{logoText}</span>
      {logoSub ? (
        <span style={{ fontWeight: 700, fontSize: 4.6 * k, letterSpacing: "0.08em", textTransform: "uppercase", marginTop: 1.5 * k }}>
          {logoSub}
        </span>
      ) : null}
    </div>
  ) : (
    <div style={{ width: 40 * k, height: 22 * k, background: "rgba(255,255,255,0.25)" }} />
  );

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {/* 1. Hero photo */}
      <AbsoluteFill style={{ clipPath: `inset(${heroIris}% ${heroIris}% ${heroIris}% ${heroIris}%)` }}>
        <AbsoluteFill style={{ transform: `scale(${heroScale})` }}>
          {src ? (
            <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <AbsoluteFill style={{ background: PHOTO_BG, justifyContent: "center", alignItems: "center" }}>
              <div style={{ width: 0.16 * Math.min(W, H), height: 0.1 * Math.min(W, H), background: "rgba(33,61,86,0.06)" }} />
            </AbsoluteFill>
          )}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* 4. Primary panel with the slash */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: seamR,
          width: W,
          height: H - seamR + 80 * k,
          background: PRIMARY,
          clipPath: `polygon(0 ${seamL - seamR}px, 100% 0, 100% 100%, 0 100%)`,
          transform: `translateY(${(1 - pPanel) * (H - seamR + 40 * k)}px)`,
        }}
      />

      {/* 2. Status pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            left: mx,
            top: tagTop,
            maxWidth: colW,
            background: ACCENT,
            color: WHITE,
            borderRadius: 999,
            padding: `${5 * k}px ${13 * k}px`,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            textTransform: "uppercase",
            fontSize: 12.5 * k,
            lineHeight: 1.1,
            ...move(pTag, -(tagTop + 40 * k)),
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 3. Price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: mx,
            top: seamR - 22 * k,
            maxWidth: colW,
            background: WHITE,
            color: INK,
            padding: `${7 * k}px ${14 * k}px`,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            fontSize: 27 * k,
            lineHeight: 1.15,
            textAlign: "right",
            ...move(pPrice, -120 * k),
          }}
        >
          {price}
        </div>
      ) : null}

      {/* 5-12. Panel content, anchored to the bottom */}
      <div
        style={{
          position: "absolute",
          left: mx,
          right: mx,
          bottom: bottomPad,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          color: WHITE,
          fontFamily: FONTS.body,
        }}
      >
        {location ? (
          <div
            style={{
              fontWeight: 600,
              fontSize: 9.5 * k,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
              lineHeight: 1.2,
              marginBottom: 6 * k,
              ...move(pEyebrow, 24 * k),
            }}
          >
            {location}
          </div>
        ) : null}
        {title ? (
          <div
            style={{
              fontWeight: 800,
              fontStyle: "italic",
              textTransform: "uppercase",
              fontSize: headSize,
              lineHeight: 0.98,
              marginBottom: 6 * k,
              ...move(pHead, 36 * k),
            }}
          >
            {title}
          </div>
        ) : null}
        {facts ? (
          <div style={{ fontWeight: 500, fontSize: 11.5 * k, lineHeight: 1.3, ...move(pFacts, 24 * k) }}>{facts}</div>
        ) : null}
        {!land && ctaEl ? <div style={{ marginTop: 12 * k, display: "flex" }}>{ctaEl}</div> : null}

        <div
          style={{
            alignSelf: "stretch",
            display: "flex",
            alignItems: "center",
            gap: 8 * k,
            marginTop: 14 * k,
            ...move(pFooter, 24 * k),
          }}
        >
          <div
            style={{
              width: 26 * k,
              height: 26 * k,
              flexShrink: 0,
              borderRadius: "50%",
              border: `${1.5 * k}px solid ${WHITE}`,
              background: AVATAR_BG,
              overflow: "hidden",
            }}
          >
            {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
          </div>
          {name ? <div style={{ fontWeight: 700, fontSize: 11 * k, lineHeight: 1.2 }}>{name}</div> : null}
          {land && ctaEl ? <div style={{ marginLeft: 16 * k, display: "flex" }}>{ctaEl}</div> : null}
          <div style={{ marginLeft: "auto", flexShrink: 0 }}>{logoEl}</div>
        </div>

        {legal ? (
          <div
            style={{
              marginTop: 10 * k,
              fontWeight: 600,
              fontSize: 6.3 * k,
              letterSpacing: "0.04em",
              textTransform: "uppercase",
              lineHeight: 1.2,
              ...move(pLegal, 16 * k),
            }}
          >
            {legal}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelStoryReveal;

