// 12. Legal line "IAD PORTUGAL S.A. | AMI: 11220", white 600 uppercase, small
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const BLUE = "#05B8E6";
const CORAL = "#F06052";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const PHOTO_BG = "#EEF0EF";
const AVATAR_BG = "#B4B7B8";

// Font size that keeps `text` within `avail` px (rough glyph-width estimate).
const fit = (text: string, base: number, avail: number, k = 0.62): number =>
  Math.min(base, avail / (Math.max(1, text.length) * k));

const ImovelNovoStory: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const p = anim.params ?? {};
  const str = (k: string): string => {
    const v = (p as Record<string, unknown>)[k];
    return v == null ? "" : String(v).trim();
  };
  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = str("tag");
  const price = str("price");
  const location = str("location");
  const title = str("title") || String(anim.text ?? "").trim();
  const facts = str("facts");
  const cta = str("cta");
  const name = str("name");
  const logoText = str("logoText");
  const logoSub = str("logoSub");
  const legal = str("legal");

  const side = format !== "portrait";
  const u =
    format === "portrait"
      ? W / 1080
      : format === "half"
        ? Math.min(W / 1080, H / 960) * 0.78
        : Math.min(W / 1920, H / 1080);

  // Staggered springs; each settles 12% of the layer after it starts, so all is still by 60%.
  const dur = Math.max(1, Math.round(0.12 * L));
  const at = (start: number, bouncy = true): number =>
    spring({
      frame: f - Math.round(start * L),
      fps,
      durationInFrames: dur,
      config: bouncy ? { damping: 9, stiffness: 140, mass: 0.8 } : { damping: 200 },
    });
  const fade = (s: number): number => Math.max(0, Math.min(1, s * 2));

  const reveal = interpolate(f, [0, Math.max(1, Math.round(0.2 * L))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const sPanel = at(0.15, false);
  const sTag = at(0.2);
  const sPrice = at(0.28);
  const sEyebrow = at(0.3, false);
  const sTitle = at(0.34);
  const sFacts = at(0.38, false);
  const sCta = at(0.42);
  const sAvatar = at(0.46);
  const sLogo = at(0.48);
  const sLegal = at(0.48, false);

  // Geometry per arrangement.
  const pw = format === "landscape" ? 0.5 : 0.44; // photo share in side layouts
  const d = H * 0.097; // half the horizontal travel of the ~11° vertical slash
  const seamTop = pw * W + d;
  const margin = (side ? 64 : 72) * u;
  const contentLeft = side ? seamTop + 56 * u : 0.066 * W;
  const contentRight = side ? margin : 0.066 * W;
  const contentW = W - contentLeft - contentRight;

  const longestWord = title.split(/\s+/).reduce((a, w) => (w.length > a.length ? w : a), "");
  const titleSize = fit(longestWord, 92 * u, contentW, 0.66);
  const ctaPad = 40 * u;
  const ctaSize = fit(cta, 52 * u, contentW - ctaPad * 2, 0.6);
  const priceAvail = side ? seamTop - 2 * d * 0.78 - margin : W * 0.87;
  const priceSize = fit(price, 84 * u, priceAvail - 80 * u, 0.66);

  const headline: React.CSSProperties = {
    fontFamily: FONTS.display,
    fontWeight: 800,
    fontStyle: "italic",
    textTransform: "uppercase",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: PHOTO_BG, overflow: "hidden" }}>
      {/* 1. Photo — top-down wipe with a settling zoom */}
      <AbsoluteFill
        style={{
          width: side ? seamTop + d : W,
          clipPath: `inset(0 0 ${(1 - reveal) * 100}% 0)`,
          overflow: "hidden",
        }}
      >
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: side ? "100%" : "64%",
              objectFit: "cover",
              transform: `scale(${1.18 - 0.18 * reveal})`,
            }}
          />
        ) : (
          <AbsoluteFill style={{ backgroundColor: PHOTO_BG }} />
        )}
      </AbsoluteFill>

      {/* 3. Blue panel with the slash */}
      <AbsoluteFill
        style={{
          backgroundColor: BLUE,
          clipPath: side
            ? `polygon(${seamTop}px 0, 100% 0, 100% 100%, ${pw * W - d}px 100%)`
            : "polygon(0 62.2%, 100% 57.2%, 100% 100%, 0 100%)",
          transform: side ? `translateX(${(1 - sPanel) * 70}%)` : `translateY(${(1 - sPanel) * 50}%)`,
        }}
      />

      {/* 2. Status pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            left: side ? margin : 0.066 * W,
            top: side ? 0.08 * H : 0.129 * H,
            maxWidth: side ? seamTop - 2 * margin : W * 0.8,
            backgroundColor: CORAL,
            color: WHITE,
            borderRadius: 999,
            padding: `${14 * u}px ${34 * u}px`,
            fontSize: 40 * u,
            lineHeight: 1,
            ...headline,
            opacity: fade(sTag),
            transform: `translateY(${(1 - sTag) * -180 * u}px)`,
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 4. Price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: side ? W - (pw * W + d - 2 * d * 0.74) - 60 * u : 0.066 * W,
            top: side ? 0.74 * H : 0.541 * H,
            maxWidth: priceAvail,
            backgroundColor: WHITE,
            color: INK,
            padding: `${20 * u}px ${40 * u}px`,
            fontSize: priceSize,
            lineHeight: 1,
            textAlign: "center",
            fontFamily: FONTS.display,
            fontWeight: 800,
            fontStyle: "italic",
            transform: `scale(${Math.max(0, sPrice)})`,
            transformOrigin: "right center",
          }}
        >
          {price}
        </div>
      ) : null}

      {/* 5–12. Panel content */}
      <div
        style={{
          position: "absolute",
          left: contentLeft,
          right: contentRight,
          top: side ? 0 : 0.635 * H,
          bottom: side ? 0 : undefined,
          display: "flex",
          flexDirection: "column",
          justifyContent: side ? "center" : "flex-start",
          color: WHITE,
        }}
      >
        {location ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.14em",
              fontSize: 30 * u,
              lineHeight: 1,
              marginBottom: 16 * u,
              opacity: fade(sEyebrow),
              transform: `translateY(${(1 - sEyebrow) * 50 * u}px)`,
            }}
          >
            {location}
          </div>
        ) : null}
        {title ? (
          <div
            style={{
              ...headline,
              fontSize: titleSize,
              lineHeight: 0.98,
              overflowWrap: "break-word",
              marginBottom: 16 * u,
              opacity: fade(sTitle),
              transform: `translateY(${(1 - sTitle) * 80 * u}px)`,
            }}
          >
            {title}
          </div>
        ) : null}
        {facts ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 500,
              fontSize: 36 * u,
              lineHeight: 1.4,
              marginBottom: 28 * u,
              opacity: fade(sFacts),
              transform: `translateY(${(1 - sFacts) * 50 * u}px)`,
            }}
          >
            {facts}
          </div>
        ) : null}
        {cta ? (
          <div
            style={{
              alignSelf: "flex-start",
              maxWidth: "100%",
              backgroundColor: CORAL,
              borderRadius: 999,
              padding: `${18 * u}px ${ctaPad}px`,
              fontFamily: FONTS.display,
              fontWeight: 800,
              fontStyle: "italic",
              fontSize: ctaSize,
              lineHeight: 1.05,
              marginBottom: 34 * u,
              transform: `scale(${Math.max(0, sCta)})`,
              transformOrigin: "left center",
            }}
          >
            {cta}
          </div>
        ) : null}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 24 * u,
            marginBottom: 28 * u,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 22 * u,
              opacity: fade(sAvatar),
              transform: `translateY(${(1 - sAvatar) * 70 * u}px)`,
            }}
          >
            <div
              style={{
                width: 74 * u,
                height: 74 * u,
                flexShrink: 0,
                borderRadius: "50%",
                border: `${4 * u}px solid ${WHITE}`,
                backgroundColor: AVATAR_BG,
                overflow: "hidden",
                boxSizing: "border-box",
              }}
            >
              {avatar ? (
                <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : null}
            </div>
            {name ? (
              <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 34 * u, lineHeight: 1.2 }}>
                {name}
              </div>
            ) : null}
          </div>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              flexShrink: 0,
              opacity: fade(sLogo),
              transform: `translateY(${(1 - sLogo) * -60 * u}px) scale(${Math.max(0, sLogo)})`,
            }}
          >
            {logo ? (
              <Img src={logo} style={{ height: 70 * u, width: "auto" }} />
            ) : (
              <>
                {logoText ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 800, fontSize: 60 * u, lineHeight: 0.9, letterSpacing: "-0.02em" }}>
                    {logoText}
                  </div>
                ) : null}
                {logoSub ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 12 * u, lineHeight: 1.2, letterSpacing: "0.08em" }}>
                    {logoSub}
                  </div>
                ) : null}
              </>
            )}
          </div>
        </div>
        {legal ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
              fontSize: 19 * u,
              lineHeight: 1.2,
              opacity: fade(sLegal),
              transform: `translateY(${(1 - sLegal) * 30 * u}px)`,
            }}
          >
            {legal}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelNovoStory;
